PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS skills (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL UNIQUE, family TEXT NOT NULL, sort_order INTEGER NOT NULL UNIQUE CHECK(sort_order>=1));
CREATE TABLE IF NOT EXISTS skill_level_assignments (id INTEGER PRIMARY KEY AUTOINCREMENT, skill_id INTEGER NOT NULL REFERENCES skills(id) ON DELETE CASCADE, level INTEGER NOT NULL CHECK(level BETWEEN 0 AND 4), rationale TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS skill_level_assignment_evidence (assignment_id INTEGER NOT NULL REFERENCES skill_level_assignments(id) ON DELETE CASCADE, evidence_id INTEGER NOT NULL REFERENCES evidence(id) ON DELETE RESTRICT, PRIMARY KEY(assignment_id,evidence_id));
CREATE TABLE IF NOT EXISTS project_catalog (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, core_integration TEXT NOT NULL, start_day INTEGER NOT NULL CHECK(start_day>=1), end_day INTEGER NOT NULL CHECK(end_day>=start_day), defence_assessment_type TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS project_records (project_id INTEGER PRIMARY KEY REFERENCES project_catalog(id) ON DELETE CASCADE, problem_statement TEXT NOT NULL DEFAULT '', repository_reference TEXT NOT NULL DEFAULT '', working_notes TEXT NOT NULL DEFAULT '', started_at TEXT, completed_at TEXT);
CREATE TABLE IF NOT EXISTS project_milestones (id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES project_catalog(id) ON DELETE CASCADE, sort_order INTEGER NOT NULL CHECK(sort_order>=1), title TEXT NOT NULL, description TEXT NOT NULL, UNIQUE(project_id,sort_order));
CREATE TABLE IF NOT EXISTS project_milestone_state (milestone_id INTEGER PRIMARY KEY REFERENCES project_milestones(id) ON DELETE CASCADE, completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN(0,1)), evidence_id INTEGER REFERENCES evidence(id) ON DELETE RESTRICT, note TEXT NOT NULL DEFAULT '', completed_at TEXT, CHECK((completed=0 AND completed_at IS NULL) OR (completed=1 AND evidence_id IS NOT NULL AND completed_at IS NOT NULL)));
